// lib-route-alert (N8N-1.3, D-N2): picks the playbook and case template for a
// raw Wazuh alert from lib-config's routing table. Pure: no calls, no state.
// Reads the raw alert defensively: missing or mistyped fields only mean "no
// match" (a missing rule.groups is not an error). A malformed alert gets the
// default route, and the playbook's normalizer parks it (N8N-1.2).
const { alert, config: cfg } = $input.first().json;
const routing = cfg?.routing;
if (!routing || !Array.isArray(routing.rows) || !cfg.playbooks) throw new Error('lib-route-alert needs the lib-config output as `config`');
const rows = routing.rows;
const def = rows[rows.length - 1];
if (!def || def.default !== true || rows.filter((r) => r.default).length !== 1) throw new Error('lib-config routing: exactly one default row, and it must be the last');

const isObj = (v) => v !== null && typeof v === 'object' && !Array.isArray(v);
const rule = isObj(alert) && isObj(alert.rule) ? alert.rule : {};
const groups = Array.isArray(rule.groups) ? rule.groups.filter((g) => typeof g === 'string') : [];
const ruleId = typeof rule.id === 'string' && rule.id.trim() !== '' ? rule.id.trim() : Number.isInteger(rule.id) ? String(rule.id) : null;
const level = Number.isInteger(rule.level) ? rule.level
  : typeof rule.level === 'string' && /^\d+$/.test(rule.level.trim()) ? Number(rule.level.trim()) : null;
// Same technique list as lib-normalize-wazuh-alert: rule.mitre.id, else rule.mitre_techniques.
const techniques = (v) => (Array.isArray(v) ? v.filter((t) => typeof t === 'string' && t.trim() !== '').map((t) => t.trim())
  : typeof v === 'string' && v.trim() !== '' ? [v.trim()] : []);
const fromMitreId = techniques(isObj(rule.mitre) ? rule.mitre.id : undefined);
const mitre = fromMitreId.length > 0 ? fromMitreId : techniques(rule.mitre_techniques);

// A clause matches when every key it has matches; it returns why, or null.
// mitre_prefix: T1110 matches T1110 and its sub-techniques (T1110.001).
const clauseMatch = (m) => {
  const why = [];
  if (m.groups_all) {
    if (!m.groups_all.every((g) => groups.includes(g))) return null;
    why.push(`groups ${m.groups_all.join('+')}`);
  }
  if (m.groups_any) {
    const hit = m.groups_any.filter((g) => groups.includes(g));
    if (hit.length === 0) return null;
    why.push(`group ${hit.join('+')}`);
  }
  if (m.rule_ids) {
    if (ruleId === null || !m.rule_ids.includes(ruleId)) return null;
    why.push(`rule ${ruleId}`);
  }
  if (m.mitre_prefix) {
    const hit = mitre.find((t) => m.mitre_prefix.some((p) => t === p || t.startsWith(`${p}.`)));
    if (!hit) return null;
    why.push(`mitre ${hit}`);
  }
  if (m.min_level !== undefined) {
    if (level === null || level < m.min_level) return null;
    why.push(`level ${level} >= ${m.min_level}`);
  }
  return why.length > 0 ? why.join(', ') : null; // an empty clause never matches
};

// Ordered, first ACTIVE match wins. A proposed row that matches is recorded
// and evaluation goes on; nothing matched -> the default row (last).
const proposed = [];
let chosen = null;
let matchedBy = null;
for (const row of rows) {
  if (row.default) break;
  const hit = (row.match ?? []).map(clauseMatch).find((w) => w !== null);
  if (!hit) continue;
  if (row.status === 'active') { chosen = row; matchedBy = hit; break; }
  proposed.push({ id: row.id, case_template: row.case_template, matched_by: hit });
}
if (!chosen) {
  chosen = def;
  matchedBy = proposed.length > 0 ? 'default (only proposed rows matched)' : 'default (no row matched)';
}

// The row's playbook, or the fallback playbook when it isn't built yet.
let playbook = chosen.playbook;
let fallback = null;
if (!cfg.playbooks[playbook]) {
  fallback = { wanted: playbook, reason: `playbook ${playbook} is not in lib-config playbooks (not built yet)` };
  playbook = routing.fallback_playbook;
}
const playbookId = cfg.playbooks[playbook];
if (!playbookId) throw new Error(`lib-config routing: fallback playbook ${playbook} has no workflow ID`);

return [{ json: { route: {
  route_id: chosen.id,
  playbook,
  playbook_id: playbookId,
  case_template: chosen.case_template,
  matched_by: matchedBy,
  fallback,
  proposed_match: proposed,
  routing_version: routing.version,
} } }];
